; ============================================================

p_newrat:

			; RATBOXN.bas 150: rx(i) = x : ry(i) = y : ox(i) = x : oy(i) = y : tx(i) = x : ty(i) = y
			dw kw_aset, arr_rx, var_newrat_i, var_newrat_x
			dw kw_aset, arr_ry, var_newrat_i, var_newrat_y
			dw kw_aset, arr_ox, var_newrat_i, var_newrat_x
			dw kw_aset, arr_oy, var_newrat_i, var_newrat_y
			dw kw_aset, arr_tx, var_newrat_i, var_newrat_x
			dw kw_aset, arr_ty, var_newrat_i, var_newrat_y

			; RATBOXN.bas 151: fd(i) = 70 : en(i) = 80 : fn(i) = 60 : hp(i) = 100 : sk(i) = 0 : pg(i) = 0 : mt(i) = -1 : mo(i) = -1 : fa(i) = -1 : fv(i) = -1
			dw kw_asetl, arr_fd, var_newrat_i, 70
			dw kw_asetl, arr_en, var_newrat_i, 80
			dw kw_asetl, arr_fn, var_newrat_i, 60
			dw kw_asetl, arr_hp, var_newrat_i, 100
			dw kw_aset8, arr_sk, var_newrat_i, lit_0
			dw kw_asetl, arr_pg, var_newrat_i, 0
			dw kw_asetl, arr_mt, var_newrat_i, -1
			dw kw_asetl, arr_mo, var_newrat_i, -1
			dw kw_asetl, arr_fa, var_newrat_i, -1
			dw kw_asetl, arr_fv, var_newrat_i, -1

			; RATBOXN.bas 152: la(i) = "" : rp2(i) = 0 : g(i) = 0 : dt(i) = 0
			dw kw_sset, arr_la, var_newrat_i, str12, 9
			dw kw_aset8, arr_rp2, var_newrat_i, lit_0
			dw kw_asetl, arr_g, var_newrat_i, 0
			dw kw_asetl, arr_dt, var_newrat_i, 0

			; RATBOXN.bas 153: sxp(i) = XPix(x) - 6 : syp(i) = YPix(y) - 4 : fc(i) = 0
			dw p_xpix_c, var_newrat_x
			dw kw_vtov, var_xpix_xpix, tmp1
			dw kw_addl, tmp1, -6, tmp1
			dw kw_aset, arr_sxp, var_newrat_i, tmp1
			dw p_ypix_c, var_newrat_y
			dw kw_vtov, var_ypix_ypix, tmp1
			dw kw_addl, tmp1, -4, tmp1
			dw kw_aset, arr_syp, var_newrat_i, tmp1
			dw kw_aset8, arr_fc, var_newrat_i, lit_0
			dw p_newrat_r

; ============================================================
; function alive (turbo mode)
; ============================================================

p_alive:

			; RATBOXN.bas 157: Dim n As Integer, q As Integer

			; RATBOXN.bas 158: n = 0
			dw kw_ztov, var_alive_n

			; RATBOXN.bas 159: For q = 0 To nr - 1
			dw kw_ztov, var_alive_q
			dw kw_addl, var_nr, -1, for30_l
			dw kw_forupv, var_alive_q, for30_l, for30_e
for30_t:

			; RATBOXN.bas 160: If st(q) >= 0 Then n = n + 1
			dw kw_aget, arr_st, var_alive_q, tmp1
			dw kw_scpgevl, tmp1, 0
			dw kw_goto_iffalse, if31_1
			dw kw_inc, var_alive_n
if31_1:

			; RATBOXN.bas 161: Next
			dw kw_next1v, var_alive_q, for30_l, for30_t
for30_e:

			; RATBOXN.bas 162: Alive = n
			dw kw_vtov, var_alive_n, var_alive_alive
			dw p_alive_r

; ============================================================
; function lim (turbo mode)
; ============================================================

p_lim:

			; RATBOXN.bas 166: If v < 0 Then v = 0
			dw kw_scpltvl, var_lim_v, 0
			dw kw_goto_iffalse, if32_1
			dw kw_ztov, var_lim_v
if32_1:

			; RATBOXN.bas 167: If v > 100 Then v = 100
			dw kw_scpgtvl, var_lim_v, 100
			dw kw_goto_iffalse, if33_1
			dw kw_ltov, 100, var_lim_v
if33_1:

			; RATBOXN.bas 168: Lim = v
			dw kw_vtov, var_lim_v, var_lim_lim
			dw p_lim_r

; ============================================================
; sub live (turbo mode)
; ============================================================

p_live:

			; RATBOXN.bas 173: Dim n As Integer, crowd As Integer, q As Integer

			; RATBOXN.bas 174: n = Alive()
			dw p_alive_c
			dw kw_vtov, var_alive_alive, var_live_n

			; RATBOXN.bas 175: crowd = 0 : If n > CAP Then crowd = 1
			dw kw_ztov, var_live_crowd
			dw kw_scpgtvl, var_live_n, 20
			dw kw_goto_iffalse, if34_1
			dw kw_ltov, 1, var_live_crowd
if34_1:

			; RATBOXN.bas 176: If tk Mod 100 = 0 Then clean = Lim(clean - np * 2 - crowd * 3)
			dw kw_l_mod, var_tk, llit_100, ltmp0
			dw kw_l_cpeq, ltmp0, llit_0
			dw kw_goto_iffalse, if35_1
			dw kw_2x, var_np, tmp1
			dw kw_subvv, var_clean, tmp1, tmp0
			dw kw_mulvl, var_live_crowd, 3, tmp1
			dw kw_subvv, tmp0, tmp1, tmp0
			dw p_lim_c, tmp0
			dw kw_vtov, var_lim_lim, var_clean
if35_1:

			; RATBOXN.bas 177: For i = 0 To nr - 1
			dw kw_ztov, var_i
			dw kw_addl, var_nr, -1, for36_l
			dw kw_forupv, var_i, for36_l, for36_e
for36_t:

			; RATBOXN.bas 178: If st(i) >= 0 Then
			dw kw_aget, arr_st, var_i, tmp0
			dw kw_scpgevl, tmp0, 0
			dw kw_goto_iffalse, if37_1

			; RATBOXN.bas 179: If tk Mod DAY = i Mod DAY Then
			dw kw_l_mod, var_tk, llit_300, ltmp0
			dw kw_modvl, var_i, 300, tmp1
			dw kw_l_itol, tmp1, ltmp1
			dw kw_l_cpeq, ltmp0, ltmp1
			dw kw_goto_iffalse, if38_1

			; RATBOXN.bas 180: age(i) = age(i) + 1
			dw kw_aget, arr_age, var_i, tmp1
			dw kw_inc, tmp1
			dw kw_aset, arr_age, var_i, tmp1

			; RATBOXN.bas 181: If st(i) = 6 And age(i) >= 3 Then st(i) = 0 : rx(i) = cx(7) - 2 : ms = Who(i) + " is weaned and leaves the pen."
			dw kw_aget, arr_st, var_i, tmp0
			dw kw_cpeqvl, tmp0, 6
			dw kw_ftov, tmp0
			dw kw_aget, arr_age, var_i, tmp1
			dw kw_scpgevl, tmp1, 3
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if39_1
			dw kw_asetl, arr_st, var_i, 0
			dw kw_addl, arr_cx+14, -2, tmp1
			dw kw_aset, arr_rx, var_i, tmp1
			dw p_who_c, var_i
			dw kw_strcpy, stmp0, var_who_who
			dw kw_strcpy, var_ms, stmp0
			dw kw_strcat, var_ms, str28
if39_1:

			; RATBOXN.bas 182: End If
if38_1:

			; RATBOXN.bas 183: q = 60 - crowd * 20
			dw kw_mulvl, var_live_crowd, 20, tmp1
			dw kw_sublv, 60, tmp1, var_live_q

			; RATBOXN.bas 184: If st(i) = 3 Then q = q * 2
			dw kw_aget, arr_st, var_i, tmp0
			dw kw_cpeqvl, tmp0, 3
			dw kw_goto_iffalse, if40_1
			dw kw_2x, var_live_q, var_live_q
if40_1:

			; RATBOXN.bas 185: If tk Mod q = i Mod q Then fd(i) = fd(i) - 1
			dw kw_l_itol, var_live_q, ltmp1
			dw kw_l_mod, var_tk, ltmp1, ltmp0
			dw kw_modvv, var_i, var_live_q, tmp1
			dw kw_l_itol, tmp1, ltmp1
			dw kw_l_cpeq, ltmp0, ltmp1
			dw kw_goto_iffalse, if41_1
			dw kw_aget, arr_fd, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_fd, var_i, tmp1
if41_1:

			; RATBOXN.bas 186: If st(i) <> 3 And tk Mod 80 = i Mod 80 Then en(i) = en(i) - 1
			dw kw_aget, arr_st, var_i, tmp0
			dw kw_cpnevl, tmp0, 3
			dw kw_ftov, tmp0
			dw kw_l_mod, var_tk, llit_80, ltmp1
			dw kw_modvl, var_i, 80, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if42_1
			dw kw_aget, arr_en, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_en, var_i, tmp1
if42_1:

			; RATBOXN.bas 187: If st(i) <> 6 And tk Mod 50 = i Mod 50 Then fn(i) = fn(i) - 1
			dw kw_aget, arr_st, var_i, tmp0
			dw kw_cpnevl, tmp0, 6
			dw kw_ftov, tmp0
			dw kw_l_mod, var_tk, llit_50, ltmp1
			dw kw_modvl, var_i, 50, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if43_1
			dw kw_aget, arr_fn, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_fn, var_i, tmp1
if43_1:

			; RATBOXN.bas 188: If tk Mod 50 = i Mod 50 And sk(i) = 0 And (clean < 40 Or fd(i) = 0) Then
			dw kw_l_mod, var_tk, llit_50, ltmp0
			dw kw_modvl, var_i, 50, tmp1
			dw kw_l_itol, tmp1, ltmp1
			dw kw_l_cpeq, ltmp0, ltmp1
			dw kw_ftov, tmp0
			dw kw_aget8, arr_sk, var_i, tmp1
			dw kw_cpeqvl, tmp1, 0
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_scpltvl, var_clean, 40
			dw kw_ftov, tmp1
			dw kw_aget, arr_fd, var_i, tmp2
			dw kw_cpeqvl, tmp2, 0
			dw kw_ftov, tmp2
			dw kw_orvv, tmp1, tmp2, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if44_1

			; RATBOXN.bas 189: If Rnd(4 - crowd) = 0 Then sk(i) = 1 : ms = Who(i) + " is ill! (M: medicine)"
			dw kw_sublv, 4, var_live_crowd, tmp0
			dw kw_rndv, tmp0, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse, if45_1
			dw kw_aset8, arr_sk, var_i, lit_1
			dw p_who_c, var_i
			dw kw_strcpy, stmp0, var_who_who
			dw kw_strcpy, var_ms, stmp0
			dw kw_strcat, var_ms, str29
if45_1:

			; RATBOXN.bas 190: End If
if44_1:

			; RATBOXN.bas 191: If sk(i) And tk Mod 20 = i Mod 20 Then hp(i) = hp(i) - 1
			dw kw_aget8, arr_sk, var_i, tmp0
			dw kw_l_mod, var_tk, llit_20, ltmp1
			dw kw_modvl, var_i, 20, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if46_1
			dw kw_aget, arr_hp, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_hp, var_i, tmp1
if46_1:

			; RATBOXN.bas 192: If (fd(i) = 0 Or en(i) = 0) And tk Mod 30 = i Mod 30 Then hp(i) = hp(i) - 1
			dw kw_aget, arr_fd, var_i, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_ftov, tmp0
			dw kw_aget, arr_en, var_i, tmp1
			dw kw_cpeqvl, tmp1, 0
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_l_mod, var_tk, llit_30, ltmp1
			dw kw_modvl, var_i, 30, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if47_1
			dw kw_aget, arr_hp, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_hp, var_i, tmp1
if47_1:

			; RATBOXN.bas 193: If sk(i) = 0 And fd(i) > 50 And en(i) > 50 And fn(i) > 40 And tk Mod 60 = i Mod 60 Then hp(i) = hp(i) + 1
			dw kw_aget8, arr_sk, var_i, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_ftov, tmp0
			dw kw_aget, arr_fd, var_i, tmp1
			dw kw_scpgtvl, tmp1, 50
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_aget, arr_en, var_i, tmp1
			dw kw_scpgtvl, tmp1, 50
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_aget, arr_fn, var_i, tmp1
			dw kw_scpgtvl, tmp1, 40
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_l_mod, var_tk, llit_60, ltmp1
			dw kw_modvl, var_i, 60, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if48_1
			dw kw_aget, arr_hp, var_i, tmp1
			dw kw_inc, tmp1
			dw kw_aset, arr_hp, var_i, tmp1
if48_1:

			; RATBOXN.bas 194: If age(i) >= 40 And tk Mod 100 = i Mod 100 Then hp(i) = hp(i) - 1    ' (old age)
			dw kw_aget, arr_age, var_i, tmp0
			dw kw_scpgevl, tmp0, 40
			dw kw_ftov, tmp0
			dw kw_l_mod, var_tk, llit_100, ltmp1
			dw kw_modvl, var_i, 100, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if49_1
			dw kw_aget, arr_hp, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_hp, var_i, tmp1
if49_1:

			; RATBOXN.bas 195: If crowd And tk Mod 200 = i Mod 200 Then                          ' (crowded: tempers fray)
			dw kw_l_mod, var_tk, llit_200, ltmp1
			dw kw_modvl, var_i, 200, tmp2
			dw kw_l_itol, tmp2, ltmp2
			dw kw_l_cpeq, ltmp1, ltmp2
			dw kw_ftov, tmp1
			dw kw_andvv, var_live_crowd, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if50_1

			; RATBOXN.bas 196: q = Rnd(nr)
			dw kw_rndv, var_nr, var_live_q

			; RATBOXN.bas 197: If q <> i Then lk(i * MAXR + q) = Lim(lk(i * MAXR + q) - 3)
			dw kw_cpnevv, var_live_q, var_i
			dw kw_goto_iffalse, if51_1
			dw kw_mulvl, var_i, 100, tmp0
			dw kw_add, tmp0, var_live_q, tmp0
			dw kw_mulvl, var_i, 100, tmp1
			dw kw_add, tmp1, var_live_q, tmp1
			dw kw_aget8, arr_lk, tmp1, tmp1
			dw kw_addl, tmp1, -3, tmp1
			dw p_lim_c, tmp1
			dw kw_aset8, arr_lk, tmp0, var_lim_lim
if51_1:

			; RATBOXN.bas 198: End If
if50_1:

			; RATBOXN.bas 199: If pg(i) > 0 Then                       ' (expecting: pg ticks to go; after a litter, pg < 0: resting)
			dw kw_aget, arr_pg, var_i, tmp0
			dw kw_scpgtvl, tmp0, 0
			dw kw_goto_iffalse, if52_1

			; RATBOXN.bas 200: pg(i) = pg(i) - 1
			dw kw_aget, arr_pg, var_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_pg, var_i, tmp1

			; RATBOXN.bas 201: If pg(i) = 0 Then Birth i
			dw kw_aget, arr_pg, var_i, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse, if52_e
			dw p_birth_c, var_i
if53_1:

			; RATBOXN.bas 202: ElseIf pg(i) < 0 Then
			dw if52_e_go
if52_1:
			dw kw_aget, arr_pg, var_i, tmp0
			dw kw_scpltvl, tmp0, 0
			dw kw_goto_iffalse, if52_2

			; RATBOXN.bas 203: pg(i) = pg(i) + 1
			dw kw_aget, arr_pg, var_i, tmp1
			dw kw_inc, tmp1
			dw kw_aset, arr_pg, var_i, tmp1

			; RATBOXN.bas 204: End If
if52_2:
if52_e:

			; RATBOXN.bas 205: fd(i) = Lim(fd(i)) : en(i) = Lim(en(i)) : fn(i) = Lim(fn(i)) : hp(i) = Lim(hp(i))
			dw kw_aget, arr_fd, var_i, tmp1
			dw p_lim_c, tmp1
			dw kw_aset, arr_fd, var_i, var_lim_lim
			dw kw_aget, arr_en, var_i, tmp1
			dw p_lim_c, tmp1
			dw kw_aset, arr_en, var_i, var_lim_lim
			dw kw_aget, arr_fn, var_i, tmp1
			dw p_lim_c, tmp1
			dw kw_aset, arr_fn, var_i, var_lim_lim
			dw kw_aget, arr_hp, var_i, tmp1
			dw p_lim_c, tmp1
			dw kw_aset, arr_hp, var_i, var_lim_lim

			; RATBOXN.bas 206: If en(i) = 0 And st(i) > 0 And st(i) < 3 Then st(i) = 3 : g(i) = 0
			dw kw_aget, arr_en, var_i, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_ftov, tmp0
			dw kw_aget, arr_st, var_i, tmp1
			dw kw_scpgtvl, tmp1, 0
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_aget, arr_st, var_i, tmp1
			dw kw_scpltvl, tmp1, 3
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if54_1
			dw kw_asetl, arr_st, var_i, 3
			dw kw_asetl, arr_g, var_i, 0
if54_1:

			; RATBOXN.bas 207: If hp(i) = 0 Then Dies i
			dw kw_aget, arr_hp, var_i, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse, if55_1
			dw p_dies_c, var_i
if55_1:

			; RATBOXN.bas 208: End If
if37_1:

			; RATBOXN.bas 209: Next
			dw kw_next1v, var_i, for36_l, for36_t
for36_e:
			dw p_live_r

; ============================================================
; function who (turbo mode)
; ============================================================

p_who:

			; RATBOXN.bas 213: If sx(i) = 0 Then Who = "#" + Trim$(Str$(i + 1)) + " (M)" Else Who = "#" + Trim$(Str$(i + 1)) + " (F)"
			dw kw_aget8, arr_sx, var_who_i, tmp1
			dw kw_cpeqvl, tmp1, 0
			dw kw_goto_iffalse, if56_1
			dw kw_addl, var_who_i, 1, tmp2
			dw kw_strstr, stmp2, tmp2
			dw kw_strtrim, stmp2, stmp2
			dw kw_strcpy, stmp1, str30
			dw kw_strcat, stmp1, stmp2
			dw kw_strcpy, var_who_who, stmp1
			dw kw_strcat, var_who_who, str31
			dw if56_e_go
if56_1:
			dw kw_addl, var_who_i, 1, tmp2
			dw kw_strstr, stmp2, tmp2
			dw kw_strtrim, stmp2, stmp2
			dw kw_strcpy, stmp1, str30
			dw kw_strcat, stmp1, stmp2
			dw kw_strcpy, var_who_who, stmp1
			dw kw_strcat, var_who_who, str32
if56_e:
			dw p_who_r

; ============================================================
; sub dies (turbo mode)
; ============================================================

p_dies:

			; RATBOXN.bas 218: st(i) = -1 : died = died + 1
			dw kw_asetl, arr_st, var_dies_i, -1
			dw kw_inc, var_died

			; RATBOXN.bas 219: Spr.Hide i
			dw fn_spr_hide, var_dies_i

			; RATBOXN.bas 220: If ng < 30 Then gx(ng) = 3 + (ng Mod 6) : gy(ng) = MY - 1 + ng \ 6 : ng = ng + 1
			dw kw_scpltvl, var_ng, 30
			dw kw_goto_iffalse, if57_1
			dw kw_modvl, var_ng, 6, tmp2
			dw kw_addl, tmp2, 3, tmp1
			dw kw_aset, arr_gx, var_ng, tmp1
			dw kw_addl, var_my, -1, tmp1
			dw kw_divvl, var_ng, 6, tmp2
			dw kw_add, tmp1, tmp2, tmp1
			dw kw_aset, arr_gy, var_ng, tmp1
			dw kw_inc, var_ng
if57_1:

			; RATBOXN.bas 221: ms = Who(i) + " has died, aged" + Str$(age(i)) + " days."
			dw p_who_c, var_dies_i
			dw kw_strcpy, stmp0, var_who_who
			dw kw_strcat, stmp0, str33
			dw kw_aget, arr_age, var_dies_i, tmp1
			dw kw_strstr, stmp1, tmp1
			dw kw_strcat, stmp0, stmp1
			dw kw_strcpy, var_ms, stmp0
			dw kw_strcat, var_ms, str34

			; RATBOXN.bas 222: If sel = i Then NextSel 1
