; ============================================================
; function tail (turbo mode)
; ============================================================

p_cybsys_tail:

			; CybSys.cls 196: Dim k As Integer, n As Integer, m As Integer, c As Integer

			; CybSys.cls 197: Tail = Trim$(System.CommandLine())
			dw fn_system_commandline, var_system_commandline_commandline
			dw kw_strcpy, stmp0, var_system_commandline_commandline
			dw kw_strtrim, stmp0, stmp0
			dw kw_strcpy, var_cybsys_tail_tail, stmp0

			; CybSys.cls 198: m = Len(Tail)
			dw kw_strlen, var_cybsys_tail_tail, var_cybsys_tail_m

			; CybSys.cls 199: n = Peek(&HF68F)
			dw kw_lptrtov8, -2417, var_cybsys_tail_n

			; CybSys.cls 200: If n > 70 Then n = 70
			dw kw_scpgtvl, var_cybsys_tail_n, 70
			dw kw_goto_iffalse, if290_1
			dw kw_ltov, 70, var_cybsys_tail_n
if290_1:

			; CybSys.cls 201: Do While n > 0                                 ' (the line's end: spaces after it left out)
do291_t:
			dw kw_scpgtvl, var_cybsys_tail_n, 0
			dw kw_goto_iffalse, do291_e

			; CybSys.cls 202: If Peek(&HF68F + n) <> 32 Then Exit Do
			dw kw_addl, var_cybsys_tail_n, -2417, tmp0
			dw kw_vptrtov8, tmp0, tmp0
			dw kw_cpnevl, tmp0, 32
			dw kw_goto_iffalse, if292_1
			dw do291_e_go
if292_1:

			; CybSys.cls 203: n = n - 1
			dw kw_dec, var_cybsys_tail_n

			; CybSys.cls 204: Loop
			dw do291_t_go
do291_e:

			; CybSys.cls 205: If n < m Or m = 0 Then Exit Function
			dw kw_scpltvv, var_cybsys_tail_n, var_cybsys_tail_m
			dw kw_ftov, tmp0
			dw kw_cpeqvl, var_cybsys_tail_m, 0
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if293_1
			dw p_cybsys_tail_r
if293_1:

			; CybSys.cls 206: For k = 1 To m                                 ' its last m characters: the tail, in capitals?
			dw kw_ltov, 1, var_cybsys_tail_k
			dw kw_vtov, var_cybsys_tail_m, for294_l
			dw kw_forupv, var_cybsys_tail_k, for294_l, for294_e
for294_t:

			; CybSys.cls 207: c = Peek(&HF68F + n - m + k)
			dw kw_addl, var_cybsys_tail_n, -2417, tmp0
			dw kw_subvv, tmp0, var_cybsys_tail_m, tmp0
			dw kw_add, tmp0, var_cybsys_tail_k, tmp0
			dw kw_vptrtov8, tmp0, var_cybsys_tail_c

			; CybSys.cls 208: If c >= 97 And c <= 122 Then c = c - 32
			dw kw_scpgevl, var_cybsys_tail_c, 97
			dw kw_ftov, tmp0
			dw kw_scplevl, var_cybsys_tail_c, 122
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if295_1
			dw kw_addl, var_cybsys_tail_c, -32, var_cybsys_tail_c
if295_1:

			; CybSys.cls 209: If c <> Asc(Mid$(Tail, k, 1)) Then Exit Function
			dw kw_strmid, stmp1, var_cybsys_tail_tail, var_cybsys_tail_k, lit_1
			dw kw_strasc, stmp1, tmp1
			dw kw_cpnevv, var_cybsys_tail_c, tmp1
			dw kw_goto_iffalse, if296_1
			dw p_cybsys_tail_r
if296_1:

			; CybSys.cls 210: Next
			dw kw_next1v, var_cybsys_tail_k, for294_l, for294_t
for294_e:

			; CybSys.cls 211: Tail = ""
			dw kw_strcpy, var_cybsys_tail_tail, str12

			; CybSys.cls 212: For k = 1 To m
			dw kw_ltov, 1, var_cybsys_tail_k
			dw kw_vtov, var_cybsys_tail_m, for297_l
			dw kw_forupv, var_cybsys_tail_k, for297_l, for297_e
for297_t:

			; CybSys.cls 213: Tail = Tail + Chr$(Peek(&HF68F + n - m + k))
			dw kw_addl, var_cybsys_tail_n, -2417, tmp1
			dw kw_subvv, tmp1, var_cybsys_tail_m, tmp1
			dw kw_add, tmp1, var_cybsys_tail_k, tmp1
			dw kw_vptrtov8, tmp1, tmp1
			dw kw_strchr, stmp1, tmp1
			dw kw_strcat, var_cybsys_tail_tail, stmp1

			; CybSys.cls 214: Next
